insert into public.ejercicios_catalogo (id, datos) values
('ABP-01', '{"id":"ABP-01","nombre":"Córner ofensivo","tipo":"Balón parado (ABP)","objetivo":"Atacar córners","fase":"ataque","niveles":["intermedio","avanzado"],"jugadoresMin":8,"jugadoresMax":22,"espacio":"Área","duracion":12,"intensidad":"media","material":"Portería, balones, petos","descripcion":"Se trabajan varias jugadas de córner: al primer palo, al segundo y en corto.","reglas":["Defensa pasiva y luego activa"],"puntosClave":["Bloqueos","Carreras sincronizadas","Golpeo preciso"],"variantes":["Córner en corto"]}'::jsonb),
('ABP-02', '{"id":"ABP-02","nombre":"Córner defensivo","tipo":"Balón parado (ABP)","objetivo":"Defender córners","fase":"defensa","niveles":["intermedio","avanzado"],"jugadoresMin":8,"jugadoresMax":22,"espacio":"Área","duracion":12,"intensidad":"media","material":"Portería, balones, petos","descripcion":"Organizar defensa de córner: zona, hombre o mixta.","reglas":["Atacantes con jugadas propias"],"puntosClave":["Ver balón y rival","Despejes","Salir rápido tras despejar"],"variantes":["Contraataque tras despejar"]}'::jsonb),
('ABP-03', '{"id":"ABP-03","nombre":"Faltas directas","tipo":"Balón parado (ABP)","objetivo":"Golpeo de falta","fase":"ataque","niveles":["intermedio","avanzado"],"jugadoresMin":2,"jugadoresMax":12,"espacio":"Frontal del área","duracion":10,"intensidad":"media","material":"Portería, balones, barrera de maniquíes","descripcion":"Golpeo de faltas desde distintas posiciones con barrera.","reglas":["Rotar lanzadores"],"puntosClave":["Superficie de golpeo","Efecto","Elegir el lado"],"variantes":["Con portero real"]}'::jsonb),
('ABP-04', '{"id":"ABP-04","nombre":"Saque de banda ofensivo","tipo":"Balón parado (ABP)","objetivo":"Aprovechar los saques de banda","fase":"ataque","niveles":["intermedio","avanzado"],"jugadoresMin":4,"jugadoresMax":12,"espacio":"Banda","duracion":10,"intensidad":"media","material":"Balones, petos","descripcion":"Jugadas preparadas de saque de banda con desmarques y descargas.","reglas":["Defensa activa"],"puntosClave":["Desmarque de apoyo","Saque rápido","Recibir y jugar"],"variantes":["Saque largo al área"]}'::jsonb),
('ABP-05', '{"id":"ABP-05","nombre":"Penaltis","tipo":"Balón parado (ABP)","objetivo":"Lanzamiento de penaltis","fase":"ataque","niveles":["iniciacion","intermedio","avanzado"],"jugadoresMin":2,"jugadoresMax":22,"espacio":"Área","duracion":10,"intensidad":"media","material":"Portería, balones","descripcion":"Tanda de penaltis con presión competitiva.","reglas":["Por equipos"],"puntosClave":["Elegir lado antes","No cambiar de idea","Golpeo seguro"],"variantes":["Con ruido o presión externa"]}'::jsonb),
('CAL-01', '{"id":"CAL-01","nombre":"Movilidad dinámica con balón","tipo":"Calentamiento","objetivo":"Activar articulaciones y tocar balón desde el minuto 1","fase":"analitico","niveles":["iniciacion","intermedio","avanzado"],"jugadoresMin":4,"jugadoresMax":30,"espacio":"20x20 m","duracion":8,"intensidad":"baja","material":"1 balón por jugador, conos","descripcion":"Cada jugador conduce libremente por el cuadrado. A la señal del entrenador hace un movimiento de movilidad (skipping, talones, aperturas de cadera, zancadas) sin perder el balón cerca.","reglas":["Nadie puede chocar con un compañero","Cambio de movimiento cada 30-45 s"],"puntosClave":["Cabeza levantada al conducir","Movimientos amplios y controlados","Aumentar ritmo poco a poco"],"variantes":["Añadir toques con interior/exterior/planta","Señales visuales (colores de conos) en vez de voz"]}'::jsonb),
('CAL-02', '{"id":"CAL-02","nombre":"Pase en parejas con desplazamiento","tipo":"Calentamiento","objetivo":"Entrar en calor con pase y control","fase":"analitico","niveles":["iniciacion","intermedio","avanzado"],"jugadoresMin":2,"jugadoresMax":30,"espacio":"Parejas a 8-10 m","duracion":8,"intensidad":"baja","material":"1 balón por pareja","descripcion":"Por parejas, se pasan el balón mientras se desplazan por el campo: pase, control orientado y vuelta a pasar. El entrenador cambia la superficie de contacto.","reglas":["Máximo 2 toques","Cambiar de superficie cada minuto"],"puntosClave":["Pase tenso y a ras de suelo","Control hacia el lado contrario al que viene el balón","Comunicarse"],"variantes":["1 toque","Pase con la pierna mala","Añadir pase aéreo corto"]}'::jsonb),
('CAL-03', '{"id":"CAL-03","nombre":"Rueda de pases en Y","tipo":"Calentamiento","objetivo":"Activación con patrón de pase y desmarque","fase":"analitico","niveles":["intermedio","avanzado"],"jugadoresMin":6,"jugadoresMax":14,"espacio":"Figura en Y de 15-20 m","duracion":10,"intensidad":"media","material":"4 conos, 2-3 balones","descripcion":"Cuatro conos forman una Y. El balón sale de la base, juega a la punta, apoyo de cara, pase al tercer hombre que abre a una de las ramas. Cada jugador sigue a su pase.","reglas":["Cada jugador va al cono al que pasa","Alternar rama derecha e izquierda"],"puntosClave":["Perfilarse antes de recibir","Pase al pie bueno del compañero","Ritmo constante"],"variantes":["Finalizar con tiro a portería","Añadir un defensor pasivo en el centro"]}'::jsonb),
('CAL-04', '{"id":"CAL-04","nombre":"Juego de los pañuelos con balón","tipo":"Calentamiento","objetivo":"Activación lúdica y velocidad de reacción","fase":"analitico","niveles":["iniciacion","intermedio"],"jugadoresMin":6,"jugadoresMax":20,"espacio":"15x15 m","duracion":8,"intensidad":"media","material":"Petos, 1 balón por jugador","descripcion":"Cada jugador lleva un peto en la cintura como cola y conduce su balón. Debe quitar colas a los demás sin perder su balón ni su peto.","reglas":["Si pierdes la cola, haces 5 toques y vuelves","Prohibido agarrar"],"puntosClave":["Proteger el balón con el cuerpo","Mirar alrededor","Cambios de ritmo"],"variantes":["Solo se puede quitar cola con la mano contraria a la pierna que conduce","Equipos: colas de un color contra otro"]}'::jsonb),
('CAL-05', '{"id":"CAL-05","nombre":"Rondo de activación 4x1","tipo":"Calentamiento","objetivo":"Activación técnica con oposición suave","fase":"ataque","niveles":["iniciacion","intermedio","avanzado"],"jugadoresMin":5,"jugadoresMax":5,"espacio":"8x8 m","duracion":6,"intensidad":"media","material":"1 balón, 4 conos","descripcion":"Cuatro jugadores en los lados de un cuadrado se pasan el balón con un defensor dentro. Si el defensor toca balón, cambia con quien perdió.","reglas":["2 toques","Cada 10 pases seguidos, punto"],"puntosClave":["Pase al pie lejano del defensor","Ofrecer línea de pase siempre","Control orientado"],"variantes":["1 toque","Dos defensores (4x2)"]}'::jsonb),
('CAL-06', '{"id":"CAL-06","nombre":"Activación neuromuscular (FIFA 11+)","tipo":"Calentamiento","objetivo":"Prevenir lesiones y preparar el cuerpo","fase":"analitico","niveles":["intermedio","avanzado"],"jugadoresMin":1,"jugadoresMax":30,"espacio":"Carril de 20 m","duracion":12,"intensidad":"media","material":"Conos","descripcion":"Circuito por carriles: carrera suave con giros de cadera, saltos laterales, planchas, sentadillas a una pierna y aceleraciones progresivas. Basado en el programa preventivo FIFA 11+.","reglas":["Ida corriendo, vuelta trotando","Mantener la técnica antes que la velocidad"],"puntosClave":["Rodillas alineadas con la punta del pie","Aterrizar suave en los saltos","Tronco estable"],"variantes":["Versión para los más pequeños con juegos en vez de series","Hacerlo por parejas para corregirse"]}'::jsonb),
('CAL-07', '{"id":"CAL-07","nombre":"Pilla-pilla con pase","tipo":"Calentamiento","objetivo":"Activación y pase bajo presión","fase":"analitico","niveles":["iniciacion","intermedio"],"jugadoresMin":8,"jugadoresMax":20,"espacio":"20x20 m","duracion":8,"intensidad":"media","material":"2-3 balones, petos","descripcion":"Dos o tres jugadores con peto pillan. Solo está a salvo quien tiene el balón en los pies. Los demás se pasan los balones para salvar a quien está en peligro.","reglas":["Quien es pillado se pone el peto","No se puede devolver el balón al que te lo pasó"],"puntosClave":["Ver al compañero en peligro","Pase rápido y preciso","Moverse a espacios libres"],"variantes":["Menos balones = más difícil","Pillar solo con balón en la mano (para los pilladores)"]}'::jsonb),
('CAL-08', '{"id":"CAL-08","nombre":"Circuito técnico de calentamiento","tipo":"Calentamiento","objetivo":"Activación con técnica individual","fase":"analitico","niveles":["iniciacion","intermedio","avanzado"],"jugadoresMin":4,"jugadoresMax":20,"espacio":"Recorrido de 25 m","duracion":10,"intensidad":"baja","material":"Conos, picas, aros, 1 balón por jugador","descripcion":"Recorrido con slalom entre conos, conducción por aros, pase contra pica o pared y recepción. Los jugadores salen en hilera cada 5 segundos.","reglas":["Salida escalonada","Si se derriba un cono, se repite el tramo"],"puntosClave":["Toques cortos en el slalom","Usar ambas piernas","Acelerar al final"],"variantes":["Cronometrar por equipos","Añadir tiro al final"]}'::jsonb),
('CON-01', '{"id":"CON-01","nombre":"Slalom de conos","tipo":"Conducción y regate","objetivo":"Conducción con cambios de dirección","fase":"analitico","niveles":["iniciacion","intermedio"],"jugadoresMin":2,"jugadoresMax":20,"espacio":"Fila de 8 conos a 1,5 m","duracion":8,"intensidad":"media","material":"8 conos por fila, balones","descripcion":"Los jugadores hacen zig-zag entre conos conduciendo el balón con distintas superficies y vuelven por fuera acelerando.","reglas":["Interior en la ida, exterior en la vuelta","Competición contra reloj"],"puntosClave":["Toques cortos","Balón pegado al pie","Levantar la vista al final"],"variantes":["Solo pierna mala","Conos a distancias irregulares"]}'::jsonb),
('CON-02', '{"id":"CON-02","nombre":"Cuadrado de regates (fintas)","tipo":"Conducción y regate","objetivo":"Aprender fintas básicas","fase":"analitico","niveles":["iniciacion","intermedio","avanzado"],"jugadoresMin":4,"jugadoresMax":20,"espacio":"15x15 m con conos centrales","duracion":10,"intensidad":"media","material":"Conos, balones","descripcion":"Cada jugador conduce hacia un cono central como si fuera un defensor, hace una finta (bicicleta, amago, cola de vaca, ruleta, pisada) y acelera hacia otro lado.","reglas":["Una finta nueva cada 2 minutos","No repetir el mismo cono seguido"],"puntosClave":["Engañar con el cuerpo, no solo con el pie","Acelerar tras la finta","Distancia de 1-2 m al cono"],"variantes":["Defensor real pasivo y luego activo","Elegir la finta según la posición del defensor"]}'::jsonb),
('CON-03', '{"id":"CON-03","nombre":"Conducción en el cuadrado con interferencias","tipo":"Conducción y regate","objetivo":"Conducir con la cabeza levantada","fase":"analitico","niveles":["iniciacion","intermedio"],"jugadoresMin":8,"jugadoresMax":24,"espacio":"20x20 m","duracion":8,"intensidad":"media","material":"Balones, conos","descripcion":"Todos conducen dentro del cuadrado. El entrenador muestra dedos o colores y los jugadores deben gritar el número/color sin parar de conducir.","reglas":["Espacio cada vez más pequeño","Quien choque hace 5 toques"],"puntosClave":["Mirar arriba cada 2-3 toques","Proteger el balón","Cambiar de ritmo"],"variantes":["Al color, ir a tocar un cono de ese color","Dos defensores robando"]}'::jsonb),
('CON-04', '{"id":"CON-04","nombre":"Cambios de dirección y ritmo","tipo":"Conducción y regate","objetivo":"Dominar giros con distintas superficies","fase":"analitico","niveles":["iniciacion","intermedio","avanzado"],"jugadoresMin":2,"jugadoresMax":20,"espacio":"Carril de 20 m","duracion":8,"intensidad":"media","material":"Conos, balones","descripcion":"Conducción recta hasta un cono, giro (interior, exterior, planta, Cruyff) y aceleración de vuelta. El entrenador indica el giro.","reglas":["Cada giro 3 repeticiones por pierna"],"puntosClave":["Frenar antes del giro","Primer toque tras el giro largo para acelerar","Cuerpo sobre el balón"],"variantes":["Giro según señal visual","Perseguidor detrás"]}'::jsonb),
('CON-05', '{"id":"CON-05","nombre":"1x1 de conducción a línea","tipo":"Conducción y regate","objetivo":"Superar al rival conduciendo","fase":"ataque","niveles":["iniciacion","intermedio","avanzado"],"jugadoresMin":2,"jugadoresMax":16,"espacio":"10x15 m","duracion":10,"intensidad":"alta","material":"Conos, balones","descripcion":"Atacante con balón intenta cruzar la línea del defensor conduciendo y parar el balón sobre ella. El defensor sale desde su línea.","reglas":["Máximo 8 s por acción","Si el defensor roba, puede marcar en la línea contraria"],"puntosClave":["Encarar con velocidad","Fintar cuando el defensor está cerca","Proteger tras regatear"],"variantes":["Dos líneas de llegada (elegir)","Defensor sale desde un lateral"]}'::jsonb),
('CON-06', '{"id":"CON-06","nombre":"Protección del balón en círculo","tipo":"Conducción y regate","objetivo":"Proteger el balón con el cuerpo","fase":"analitico","niveles":["iniciacion","intermedio","avanzado"],"jugadoresMin":2,"jugadoresMax":20,"espacio":"Círculo de 5 m por pareja","duracion":6,"intensidad":"alta","material":"Balones, conos","descripcion":"Por parejas en un círculo. Uno protege el balón y el otro intenta sacarlo del círculo. 30 s y cambio.","reglas":["Prohibido agarrar","Punto por cada 10 s sin perder el balón"],"puntosClave":["Cuerpo entre rival y balón","Brazos abiertos sin empujar","Pisar el balón con la planta para girar"],"variantes":["Dos atacantes contra uno","Tras proteger, salir conduciendo a una puerta"]}'::jsonb),
('CON-07', '{"id":"CON-07","nombre":"Conducción en carrera con salida rápida","tipo":"Conducción y regate","objetivo":"Conducción a velocidad en espacio amplio","fase":"analitico","niveles":["intermedio","avanzado"],"jugadoresMin":2,"jugadoresMax":20,"espacio":"30 m","duracion":8,"intensidad":"alta","material":"Conos, balones","descripcion":"Conducción a máxima velocidad durante 25-30 m con pocos toques largos. Por parejas en competición.","reglas":["Gana quien para el balón primero en la meta"],"puntosClave":["Toques largos con el empeine exterior","No perder el control","Frenar con la planta"],"variantes":["Con perseguidor","Terminar con tiro"]}'::jsonb),
('CON-08', '{"id":"CON-08","nombre":"Regate a mini porterías","tipo":"Conducción y regate","objetivo":"Regatear y finalizar","fase":"ataque","niveles":["iniciacion","intermedio"],"jugadoresMin":2,"jugadoresMax":16,"espacio":"15x20 m con 4 mini porterías","duracion":10,"intensidad":"alta","material":"4 mini porterías, balones, petos","descripcion":"1x1 en un espacio con 4 mini porterías. El atacante puede marcar conduciendo en cualquiera de ellas. El defensor marca en dos puertas si roba.","reglas":["Gol solo conduciendo","Rotar cada 30 s"],"puntosClave":["Mirar dónde hay menos defensa","Cambiar de dirección para engañar","Atacar rápido"],"variantes":["2x2","Gol vale doble con pierna mala"]}'::jsonb),
('COO-01', '{"id":"COO-01","nombre":"Escalera de coordinación + pase","tipo":"Coordinación y juegos motores","objetivo":"Mejorar frecuencia de apoyos y coordinación","fase":"analitico","niveles":["iniciacion","intermedio","avanzado"],"jugadoresMin":2,"jugadoresMax":16,"espacio":"Escalera + 10 m","duracion":10,"intensidad":"media","material":"Escalera de agilidad, conos, balones","descripcion":"El jugador hace un patrón en la escalera (un pie por hueco, dos pies, lateral, dentro-fuera) y al salir recibe un pase del entrenador y lo devuelve.","reglas":["Cambiar de patrón cada 2 series","Si pisa un travesaño, repite"],"puntosClave":["Apoyos rápidos sobre la punta del pie","Brazos acompañan","Mirar el balón al salir"],"variantes":["Recibir y tirar a portería","Usar aros o conos si no hay escalera"]}'::jsonb),
('COO-02', '{"id":"COO-02","nombre":"Semáforo","tipo":"Coordinación y juegos motores","objetivo":"Reacción a estímulos y control del balón","fase":"analitico","niveles":["iniciacion"],"jugadoresMin":4,"jugadoresMax":20,"espacio":"15x15 m","duracion":8,"intensidad":"baja","material":"1 balón por jugador, conos de colores","descripcion":"Los niños conducen libremente. Verde = conducir rápido; amarillo = conducir despacio; rojo = parar el balón con la planta y sentarse encima.","reglas":["El último en reaccionar hace 3 toques extra","Añadir colores nuevos según se dominen"],"puntosClave":["Balón siempre cerca","Escuchar/ver la señal","Frenar con la planta"],"variantes":["Azul = cambio de dirección","Señales con conos levantados en vez de voz"]}'::jsonb),
('COO-03', '{"id":"COO-03","nombre":"Los piratas y el tesoro","tipo":"Coordinación y juegos motores","objetivo":"Conducción, protección y diversión","fase":"analitico","niveles":["iniciacion"],"jugadoresMin":6,"jugadoresMax":20,"espacio":"Campo con 4 casas (aros)","duracion":10,"intensidad":"media","material":"Aros, muchos balones, petos","descripcion":"En el centro hay muchos balones (el tesoro). Cuatro equipos tienen una casa cada uno. Deben llevar balones conduciendo a su casa. Cuando se acaba el centro, pueden robar en otras casas.","reglas":["Solo un balón por viaje","No se puede defender la propia casa"],"puntosClave":["Conducir rápido con la cabeza alta","Elegir la casa con más balones","Trabajo en equipo"],"variantes":["Uno de cada equipo puede defender","Balones traídos con la mano para los más pequeños"]}'::jsonb),
('COO-04', '{"id":"COO-04","nombre":"Malabares (toques) por niveles","tipo":"Coordinación y juegos motores","objetivo":"Sensibilidad con el balón","fase":"analitico","niveles":["iniciacion","intermedio","avanzado"],"jugadoresMin":1,"jugadoresMax":30,"espacio":"Libre","duracion":8,"intensidad":"baja","material":"1 balón por jugador","descripcion":"Cada jugador intenta encadenar toques sin que caiga el balón: nivel 1 con bote entre toques, nivel 2 sin bote con pie bueno, nivel 3 alternando pies, nivel 4 pie-muslo-cabeza.","reglas":["Cada jugador busca su récord","Pasar de nivel al hacer 10 seguidos"],"puntosClave":["Golpear con el empeine y tobillo firme","Toques suaves y bajos","Mirar el balón"],"variantes":["Por parejas pasándose sin que caiga","Competición por equipos sumando toques"]}'::jsonb),
('COO-05', '{"id":"COO-05","nombre":"Carrera de relevos con conducción","tipo":"Coordinación y juegos motores","objetivo":"Velocidad con balón y competición","fase":"analitico","niveles":["iniciacion","intermedio"],"jugadoresMin":6,"jugadoresMax":24,"espacio":"Carriles de 15 m","duracion":8,"intensidad":"alta","material":"Conos, balones","descripcion":"Equipos en hilera. Cada jugador conduce hasta un cono, lo rodea y vuelve para entregar el balón al siguiente. Gana el equipo que termina antes.","reglas":["El balón se entrega parado al pie","Si el balón sale del carril, vuelta al inicio del tramo"],"puntosClave":["Toques más largos en recto y cortos al girar","Girar con el exterior","Animar al equipo"],"variantes":["Slalom en vez de recto","Conducir con la pierna mala"]}'::jsonb),
('COO-06', '{"id":"COO-06","nombre":"Cruzar el río (tiburones)","tipo":"Coordinación y juegos motores","objetivo":"Regate y protección en situación lúdica","fase":"ataque","niveles":["iniciacion","intermedio"],"jugadoresMin":8,"jugadoresMax":20,"espacio":"20x25 m","duracion":8,"intensidad":"media","material":"Balones, petos","descripcion":"Los jugadores con balón deben cruzar el campo (el río) sin que los tiburones del centro les roben. Quien pierde el balón pasa a ser tiburón.","reglas":["Salida a la señal","Gana el último que sobrevive"],"puntosClave":["Cambios de ritmo y dirección","Encarar al hueco","Proteger con el cuerpo"],"variantes":["Tiburones solo se mueven lateralmente","Zonas seguras (islas) en mitad del campo"]}'::jsonb),
('COO-07', '{"id":"COO-07","nombre":"Circuito de habilidades motrices","tipo":"Coordinación y juegos motores","objetivo":"Desarrollar saltos, giros y equilibrio","fase":"analitico","niveles":["iniciacion"],"jugadoresMin":4,"jugadoresMax":20,"espacio":"Circuito de 20 m","duracion":10,"intensidad":"media","material":"Vallas pequeñas, aros, conos, colchoneta","descripcion":"Recorrido con saltos a pies juntos por aros, vallas a una pierna, voltereta, carrera lateral y conducción final hasta una mini portería.","reglas":["Salida cada 5 s","Completar sin saltarse estaciones"],"puntosClave":["Aterrizar con las dos piernas flexionadas","Mantener equilibrio","Diversión sobre velocidad"],"variantes":["Cambiar el orden de estaciones","Hacerlo por parejas de la mano"]}'::jsonb),
('COO-08', '{"id":"COO-08","nombre":"Espejo","tipo":"Coordinación y juegos motores","objetivo":"Reacción y coordinación por parejas","fase":"analitico","niveles":["iniciacion","intermedio"],"jugadoresMin":2,"jugadoresMax":30,"espacio":"Parejas en 5x5 m","duracion":6,"intensidad":"media","material":"Conos","descripcion":"Por parejas enfrentadas. Uno hace movimientos (laterales, adelante, atrás, agacharse) y el otro los copia como un espejo. Cambiar de rol cada 30 s.","reglas":["Prohibido tocarse","Movimientos cortos y rápidos"],"puntosClave":["Mirar a la cadera del compañero","Pasos cortos","Postura baja"],"variantes":["Con balón en los pies","Al silbato, el espejo debe tocar un cono antes que el guía"]}'::jsonb),
('DEF-01', '{"id":"DEF-01","nombre":"Entrada y temporización 1x1","tipo":"Defensa","objetivo":"Defensa individual: perfil y paciencia","fase":"defensa","niveles":["intermedio","avanzado"],"jugadoresMin":2,"jugadoresMax":16,"espacio":"10x15 m","duracion":10,"intensidad":"alta","material":"Conos, balones","descripcion":"El defensor debe impedir que el atacante cruce la línea. Se trabaja aproximación, perfil y momento de entrada.","reglas":["Atacante solo puede ganar conduciendo"],"puntosClave":["Perfil cerrando el lado bueno","Distancia de 1-1,5 m","Entrar cuando el balón se separa"],"variantes":["Defensor empieza de espaldas","Atacante con comodín"]}'::jsonb),
('DEF-02', '{"id":"DEF-02","nombre":"Coberturas 2x2","tipo":"Defensa","objetivo":"Defensa y cobertura","fase":"defensa","niveles":["intermedio","avanzado"],"jugadoresMin":4,"jugadoresMax":16,"espacio":"15x20 m con portería","duracion":10,"intensidad":"alta","material":"Portería, balones, petos","descripcion":"Dos defensores contra dos atacantes. Un defensor presiona al poseedor y el otro hace cobertura.","reglas":["Gol solo conduciendo"],"puntosClave":["Presión al poseedor","Compañero en diagonal detrás","Comunicar"],"variantes":["3x3 con permutas","Atacante extra"]}'::jsonb),
